const ELEMENT_PROP_KEYS = new Set(["theme","accent","text","italicWords","looseness","stagger","pullAt","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  text: "From rough to ready.",
  italicWords: 1,
  looseness: 0.15,
  stagger: 2,
  pullAt: 46,
  fontFamily: "Instrument Serif",
  scale: 1,
  delay: 0,
  speed: 1,
};

type PathTextElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PathTextBase>;

const PathTextInner = forwardRef<
  HTMLDivElement,
  PathTextElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PathText>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PathTextBase
          {...(componentProps as unknown as ComponentProps<typeof PathTextBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PathText = Interactive.withSchema({
